/* ============================================================
   Alert.module.css
   ============================================================ */

.alert {
  font-family: var(--font-family, system-ui, -apple-system, sans-serif);
  border-radius: var(--radius-md, 4px);
  padding: var(--spacing-2, 8px) var(--spacing-4, 16px);
  display: flex;
  align-items: flex-start;
  font-size: var(--font-size-sm, 0.875rem);
  line-height: 1.5;
  box-sizing: border-box;
}

/* ============================================================
   ELEMENTS
   ============================================================ */

.icon {
  display: inherit;
  margin-right: var(--spacing-3, 12px);
  padding: var(--spacing-1, 4px) 0;
}

.icon svg {
  width: 20px;
  height: 20px;
  fill: none;
}

.message {
  padding: var(--spacing-1, 4px) 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  flex: 1 1 auto;
  min-width: 0;
}

.title {
  font-weight: var(--font-weight-medium, 500);
  font-size: var(--font-size-md, 1rem);
  margin-bottom: var(--spacing-1, 4px);
}

.closeButton {
  margin-left: auto;
  margin-right: calc(var(--spacing-2, 8px) * -1);
  padding: var(--spacing-1, 4px);
  background: transparent;
  border: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-full, 9999px);
  color: inherit;
  opacity: 0.7;
  transition: background-color var(--transition-fast, 150ms ease), opacity var(--transition-fast, 150ms ease);
}

.closeButton:hover {
  opacity: 1;
  background-color: rgba(0, 0, 0, 0.08);
}

.closeButton svg {
  width: 18px;
  height: 18px;
}

/* ============================================================
   VARIANTS & SEVERITIES
   ============================================================ */

/* --- Standard Variant (Subtle background) --- */
.alert[data-variant="standard"][data-severity="success"] {
  background-color: var(--success-subtle, rgba(46, 125, 50, 0.12));
  color: var(--success-foreground-subtle, #1e4620);
}
.alert[data-variant="standard"][data-severity="success"] .icon { color: var(--success, #2e7d32); }

.alert[data-variant="standard"][data-severity="info"] {
  background-color: var(--info-subtle, rgba(2, 136, 209, 0.12));
  color: var(--info-foreground-subtle, #014361);
}
.alert[data-variant="standard"][data-severity="info"] .icon { color: var(--info, #0288d1); }

.alert[data-variant="standard"][data-severity="warning"] {
  background-color: var(--warning-subtle, rgba(237, 108, 2, 0.12));
  color: var(--warning-foreground-subtle, #4d2700);
}
.alert[data-variant="standard"][data-severity="warning"] .icon { color: var(--warning, #ed6c02); }

.alert[data-variant="standard"][data-severity="error"] {
  background-color: var(--error-subtle, rgba(211, 47, 47, 0.12));
  color: var(--error-foreground-subtle, #5f2120);
}
.alert[data-variant="standard"][data-severity="error"] .icon { color: var(--error, #d32f2f); }

/* --- Filled Variant (Solid background) --- */
.alert[data-variant="filled"][data-severity="success"] {
  background-color: var(--success, #2e7d32);
  color: var(--success-foreground, #ffffff);
}
.alert[data-variant="filled"][data-severity="success"] .closeButton:hover { background-color: rgba(255, 255, 255, 0.2); }

.alert[data-variant="filled"][data-severity="info"] {
  background-color: var(--info, #0288d1);
  color: var(--info-foreground, #ffffff);
}
.alert[data-variant="filled"][data-severity="info"] .closeButton:hover { background-color: rgba(255, 255, 255, 0.2); }

.alert[data-variant="filled"][data-severity="warning"] {
  background-color: var(--warning, #ed6c02);
  color: var(--warning-foreground, #ffffff);
}
.alert[data-variant="filled"][data-severity="warning"] .closeButton:hover { background-color: rgba(255, 255, 255, 0.2); }

.alert[data-variant="filled"][data-severity="error"] {
  background-color: var(--error, #d32f2f);
  color: var(--error-foreground, #ffffff);
}
.alert[data-variant="filled"][data-severity="error"] .closeButton:hover { background-color: rgba(255, 255, 255, 0.2); }

/* --- Outlined Variant (Transparent bg with border) --- */
.alert[data-variant="outlined"] {
  border: 1px solid;
  background-color: transparent;
}

.alert[data-variant="outlined"][data-severity="success"] {
  border-color: var(--success, #2e7d32);
  color: var(--success-foreground-subtle, #1e4620);
}
.alert[data-variant="outlined"][data-severity="success"] .icon { color: var(--success, #2e7d32); }

.alert[data-variant="outlined"][data-severity="info"] {
  border-color: var(--info, #0288d1);
  color: var(--info-foreground-subtle, #014361);
}
.alert[data-variant="outlined"][data-severity="info"] .icon { color: var(--info, #0288d1); }

.alert[data-variant="outlined"][data-severity="warning"] {
  border-color: var(--warning, #ed6c02);
  color: var(--warning-foreground-subtle, #4d2700);
}
.alert[data-variant="outlined"][data-severity="warning"] .icon { color: var(--warning, #ed6c02); }

.alert[data-variant="outlined"][data-severity="error"] {
  border-color: var(--error, #d32f2f);
  color: var(--error-foreground-subtle, #5f2120);
}
.alert[data-variant="outlined"][data-severity="error"] .icon { color: var(--error, #d32f2f); }

import React from "react";
import styles from "./Alert.module.css";
import { cp } from "../../../lib/utils";

export type AlertSeverity = "success" | "info" | "warning" | "error";
export type AlertVariant = "standard" | "filled" | "outlined";

export interface AlertProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  severity?: AlertSeverity;
  variant?: AlertVariant;
  icon?: React.ReactNode;
  onClose?: (event: React.MouseEvent<HTMLButtonElement, MouseEvent>) => void;
  title?: React.ReactNode;
}

const defaultIcons = {
  success: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path>
      <polyline points="22 4 12 14.01 9 11.01"></polyline>
    </svg>
  ),
  info: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <circle cx="12" cy="12" r="10"></circle>
      <line x1="12" y1="16" x2="12" y2="12"></line>
      <line x1="12" y1="8" x2="12.01" y2="8"></line>
    </svg>
  ),
  warning: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"></path>
      <line x1="12" y1="9" x2="12" y2="13"></line>
      <line x1="12" y1="17" x2="12.01" y2="17"></line>
    </svg>
  ),
  error: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <circle cx="12" cy="12" r="10"></circle>
      <line x1="15" y1="9" x2="9" y2="15"></line>
      <line x1="9" y1="9" x2="15" y2="15"></line>
    </svg>
  ),
};

export const Alert = React.forwardRef<HTMLDivElement, AlertProps>(
  (
    {
      className,
      severity = "success",
      variant = "standard",
      icon,
      onClose,
      title,
      children,
      ...props
    },
    ref
  ) => {
    return (
      <div
        ref={ref}
        role="alert"
        data-severity={severity}
        data-variant={variant}
        className={cp(styles.alert, className)}
        {...props}
      >
        <div className={styles.icon}>
          {icon !== false ? (icon || defaultIcons[severity]) : null}
        </div>
        <div className={styles.message}>
          {title && <div className={styles.title}>{title}</div>}
          {children}
        </div>
        {onClose && (
          <button
            type="button"
            className={styles.closeButton}
            onClick={onClose}
            aria-label="Close"
          >
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <line x1="18" y1="6" x2="6" y2="18"></line>
              <line x1="6" y1="6" x2="18" y2="18"></line>
            </svg>
          </button>
        )}
      </div>
    );
  }
);

Alert.displayName = "Alert";

/* ============================================================
   AppBar.module.css
   ============================================================ */

.appBar {
  display: flex;
  flex-direction: column;
  width: 100%;
  box-sizing: border-box;
  flex-shrink: 0;
  z-index: 1100;
}

/* Positions */
.appBar[data-position="fixed"] {
  position: fixed;
  top: 0;
  left: auto;
  right: 0;
}
.appBar[data-position="absolute"] {
  position: absolute;
  top: 0;
  left: auto;
  right: 0;
}
.appBar[data-position="sticky"] {
  position: sticky;
  top: 0;
  left: auto;
  right: 0;
}
.appBar[data-position="static"] {
  position: static;
}
.appBar[data-position="relative"] {
  position: relative;
}

/* Colors */
.appBar[data-color="primary"] {
  background-color: var(--primary, #1976d2);
  color: var(--primary-contrast, #ffffff);
}
.appBar[data-color="secondary"] {
  background-color: var(--secondary, #9c27b0);
  color: var(--secondary-contrast, #ffffff);
}
.appBar[data-color="default"] {
  background-color: var(--background-default, #f5f5f5);
  color: var(--text-primary, rgba(0, 0, 0, 0.87));
}
.appBar[data-color="transparent"] {
  background-color: transparent;
  color: inherit;
  box-shadow: none;
}
.appBar[data-color="inherit"] {
  color: inherit;
}

/* ============================================================
   TOOLBAR
   ============================================================ */
.toolbar {
  position: relative;
  display: flex;
  align-items: center;
  padding-left: var(--spacing-4, 16px);
  padding-right: var(--spacing-4, 16px);
  min-height: 56px;
}

@media (min-width: 600px) {
  .toolbar {
    padding-left: var(--spacing-6, 24px);
    padding-right: var(--spacing-6, 24px);
    min-height: 64px;
  }
}

.toolbar[data-variant="dense"] {
  min-height: 48px;
}

.toolbar[data-disable-gutters="true"] {
  padding-left: 0;
  padding-right: 0;
}

import React from "react";
import styles from "./AppBar.module.css";
import { cp } from "../../../lib/utils";
import { Paper, PaperProps } from "../Paper";

// ==========================================
// AppBar Component
// ==========================================
export interface AppBarProps extends PaperProps {
  color?: "primary" | "secondary" | "default" | "transparent" | "inherit";
  position?: "fixed" | "absolute" | "sticky" | "static" | "relative";
}

export const AppBar = React.forwardRef<HTMLDivElement, AppBarProps>(
  ({ className, color = "primary", position = "fixed", elevation = 4, square = true, ...props }, ref) => {
    return (
      <Paper
        ref={ref}
        square={square}
        elevation={elevation}
        className={cp(styles.appBar, className)}
        data-color={color}
        data-position={position}
        {...props}
      />
    );
  }
);
AppBar.displayName = "AppBar";

// ==========================================
// Toolbar Component
// ==========================================
export interface ToolbarProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: "regular" | "dense";
  disableGutters?: boolean;
}

export const Toolbar = React.forwardRef<HTMLDivElement, ToolbarProps>(
  ({ className, variant = "regular", disableGutters = false, ...props }, ref) => {
    return (
      <div
        ref={ref}
        className={cp(styles.toolbar, className)}
        data-variant={variant}
        data-disable-gutters={disableGutters || undefined}
        {...props}
      />
    );
  }
);
Toolbar.displayName = "Toolbar";

/* ============================================================
   Avatar.module.css
   ============================================================ */

.avatar {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  font-family: var(--font-family, system-ui, -apple-system, sans-serif);
  font-size: 1.25rem;
  line-height: 1;
  overflow: hidden;
  user-select: none;
}

/* ============================================================
   VARIANTS (Shapes)
   ============================================================ */
.avatar[data-variant="circular"] {
  border-radius: 50%;
}

.avatar[data-variant="rounded"] {
  border-radius: var(--radius-md, 4px);
}

.avatar[data-variant="square"] {
  border-radius: 0;
}

/* ============================================================
   COLORS
   ============================================================ */
.avatar[data-color="default"] {
  background-color: var(--action-disabled-bg, rgba(0, 0, 0, 0.26));
  color: var(--background-paper, #ffffff);
}

.avatar[data-color="primary"] {
  background-color: var(--primary, #1976d2);
  color: var(--primary-foreground, #ffffff);
}

.avatar[data-color="secondary"] {
  background-color: var(--secondary, #9c27b0);
  color: var(--secondary-foreground, #ffffff);
}

.avatar[data-color="error"] {
  background-color: var(--error, #d32f2f);
  color: var(--error-foreground, #ffffff);
}

.avatar[data-color="warning"] {
  background-color: var(--warning, #ed6c02);
  color: var(--warning-foreground, #ffffff);
}

.avatar[data-color="info"] {
  background-color: var(--info, #0288d1);
  color: var(--info-foreground, #ffffff);
}

.avatar[data-color="success"] {
  background-color: var(--success, #2e7d32);
  color: var(--success-foreground, #ffffff);
}

/* ============================================================
   ELEMENTS
   ============================================================ */
.image {
  width: 100%;
  height: 100%;
  text-align: center;
  object-fit: cover;
  color: transparent;
  text-indent: 10000px;
}

.defaultIcon {
  width: 75%;
  height: 75%;
}

import React, { useState } from "react";
import styles from "./Avatar.module.css";
import { cp } from "../../../lib/utils";

export type AvatarVariant = "circular" | "rounded" | "square";
export type AvatarColor =
  | "primary"
  | "secondary"
  | "error"
  | "warning"
  | "info"
  | "success"
  | "default";

export interface AvatarProps extends React.HTMLAttributes<HTMLDivElement> {
  src?: string;
  alt?: string;
  srcSet?: string;
  variant?: AvatarVariant;
  color?: AvatarColor;
}

const defaultIcon = (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={styles.defaultIcon}>
    <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path>
    <circle cx="12" cy="7" r="4"></circle>
  </svg>
);

export const Avatar = React.forwardRef<HTMLDivElement, AvatarProps>(
  (
    {
      className,
      src,
      alt,
      srcSet,
      variant = "circular",
      color = "default",
      children,
      ...props
    },
    ref
  ) => {
    const [hasError, setHasError] = useState(false);

    const hasImage = src || srcSet;
    const hasImageAndNoError = hasImage && !hasError;

    return (
      <div
        ref={ref}
        data-variant={variant}
        data-color={color}
        className={cp(styles.avatar, className)}
        {...props}
      >
        {hasImageAndNoError ? (
          <img
            src={src}
            alt={alt}
            srcSet={srcSet}
            className={styles.image}
            onError={() => setHasError(true)}
          />
        ) : children != null ? (
          children
        ) : (
          defaultIcon
        )}
      </div>
    );
  }
);

Avatar.displayName = "Avatar";

/* ============================================================
   Badge.module.css
   ============================================================ */

.root {
  position: relative;
  display: inline-flex;
  vertical-align: middle;
  flex-shrink: 0;
}

.badge {
  display: flex;
  flex-wrap: wrap;
  place-content: center;
  align-items: center;
  position: absolute;
  box-sizing: border-box;
  font-family: var(--font-family, system-ui, -apple-system, sans-serif);
  font-weight: var(--font-weight-medium, 500);
  font-size: var(--font-size-xs, 0.75rem);
  line-height: 1;
  border-radius: var(--radius-full, 9999px);
  z-index: 1;
  transition: transform var(--transition-normal, 200ms ease);
}

/* ============================================================
   VARIANTS
   ============================================================ */

/* Standard Badge */
.badge[data-variant="standard"] {
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  top: 0;
  right: 0;
  transform: scale(1) translate(50%, -50%);
  transform-origin: 100% 0%;
}

/* Dot Badge */
.badge[data-variant="dot"] {
  min-width: 8px;
  height: 8px;
  padding: 0;
  top: 0;
  right: 0;
  transform: scale(1) translate(50%, -50%);
  transform-origin: 100% 0%;
}

/* Invisible state */
.badge[data-invisible] {
  transform: scale(0) translate(50%, -50%);
}

/* ============================================================
   COLORS
   ============================================================ */
.badge[data-color="default"] {
  background-color: var(--action-disabled-bg, rgba(0, 0, 0, 0.26));
  color: var(--background-paper, #ffffff);
}

.badge[data-color="primary"] {
  background-color: var(--primary, #1976d2);
  color: var(--primary-foreground, #ffffff);
}

.badge[data-color="secondary"] {
  background-color: var(--secondary, #9c27b0);
  color: var(--secondary-foreground, #ffffff);
}

.badge[data-color="error"] {
  background-color: var(--error, #d32f2f);
  color: var(--error-foreground, #ffffff);
}

.badge[data-color="warning"] {
  background-color: var(--warning, #ed6c02);
  color: var(--warning-foreground, #ffffff);
}

.badge[data-color="info"] {
  background-color: var(--info, #0288d1);
  color: var(--info-foreground, #ffffff);
}

.badge[data-color="success"] {
  background-color: var(--success, #2e7d32);
  color: var(--success-foreground, #ffffff);
}

import React from "react";
import styles from "./Badge.module.css";
import { cp } from "../../../lib/utils";

export type BadgeColor =
  | "primary"
  | "secondary"
  | "error"
  | "warning"
  | "info"
  | "success"
  | "default";

export type BadgeVariant = "standard" | "dot";

export interface BadgeProps extends React.HTMLAttributes<HTMLDivElement> {
  badgeContent?: React.ReactNode;
  color?: BadgeColor;
  variant?: BadgeVariant;
  max?: number;
  showZero?: boolean;
  invisible?: boolean;
}

export const Badge = React.forwardRef<HTMLDivElement, BadgeProps>(
  (
    {
      className,
      badgeContent,
      color = "primary",
      variant = "standard",
      max = 99,
      showZero = false,
      invisible = false,
      children,
      ...props
    },
    ref
  ) => {
    let displayValue: React.ReactNode = badgeContent;

    if (variant !== "dot" && typeof badgeContent === "number") {
      if (badgeContent > max) {
        displayValue = `${max}+`;
      } else if (badgeContent === 0 && !showZero) {
        invisible = true;
      }
    }

    const isHidden = invisible || (variant === "standard" && (badgeContent === undefined || badgeContent === null));

    return (
      <div className={cp(styles.root, className)} ref={ref} {...props}>
        {children}
        <span
          data-color={color}
          data-variant={variant}
          data-invisible={isHidden || undefined}
          className={styles.badge}
        >
          {variant === "standard" ? displayValue : null}
        </span>
      </div>
    );
  }
);

Badge.displayName = "Badge";

/* ============================================================
   Box.module.css
   ============================================================ */

.box {
  /* Box is a generic container, it doesn't have inherent styles by default,
     but it provides a hook for theming if needed. */
  box-sizing: border-box;
}

import React from "react";
import styles from "./Box.module.css";
import { cp } from "../../../lib/utils";

export interface BoxProps extends React.HTMLAttributes<HTMLElement> {
  component?: React.ElementType;
}

export const Box = React.forwardRef<HTMLElement, BoxProps>(
  ({ className, component: Component = "div", ...props }, ref) => {
    return <Component ref={ref} className={cp(styles.box, className)} {...props} />;
  }
);
Box.displayName = "Box";

/* ============================================================
   Breadcrumbs.module.css
   ============================================================ */

.root {
  font-family: var(--font-family, system-ui, -apple-system, sans-serif);
  color: var(--text-secondary, rgba(0, 0, 0, 0.6));
}

.ol {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  padding: 0;
  margin: 0;
  list-style: none;
}

.li {
  display: inline-flex;
  align-items: center;
}

/* ============================================================
   ITEMS
   ============================================================ */
.item {
  color: inherit;
  text-decoration: none;
  transition: color var(--transition-fast, 150ms ease);
}

.item:hover {
  text-decoration: underline;
  color: var(--text-primary, rgba(0, 0, 0, 0.87));
}

.lastItem {
  color: var(--text-primary, rgba(0, 0, 0, 0.87));
  text-decoration: none;
  font-weight: var(--font-weight-regular, 400);
}

.separator {
  display: flex;
  user-select: none;
  margin-left: var(--spacing-1, 8px);
  margin-right: var(--spacing-1, 8px);
  color: var(--text-secondary, rgba(0, 0, 0, 0.6));
}

.separator svg {
  width: 16px;
  height: 16px;
}

.ellipsis {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  background-color: var(--action-hover, rgba(0, 0, 0, 0.04));
  border-radius: var(--radius-sm, 2px);
  letter-spacing: 2px;
  font-size: var(--font-size-xs, 0.75rem);
}

import React, { Children } from "react";
import styles from "./Breadcrumbs.module.css";
import { cp } from "../../../lib/utils";

export interface BreadcrumbsProps extends React.HTMLAttributes<HTMLElement> {
  separator?: React.ReactNode;
  maxItems?: number;
}

export const Breadcrumbs = React.forwardRef<HTMLElement, BreadcrumbsProps>(
  ({ className, separator = "/", maxItems = 8, children, ...props }, ref) => {
    const allChildren = Children.toArray(children).filter((child) => React.isValidElement(child));

    let renderChildren = allChildren;
    if (allChildren.length > maxItems) {
      renderChildren = [
        allChildren[0],
        <span key="ellipsis" className={styles.ellipsis}>...</span>,
        ...allChildren.slice(allChildren.length - (maxItems - 1))
      ];
    }

    return (
      <nav
        ref={ref}
        aria-label="breadcrumb"
        className={cp(styles.root, className)}
        {...props}
      >
        <ol className={styles.ol}>
          {renderChildren.map((child, index) => {
            const isLast = index === renderChildren.length - 1;
            return (
              <li className={styles.li} key={`breadcrumb-${index}`}>
                {React.isValidElement(child) ? React.cloneElement(child as React.ReactElement<any>, {
                   'aria-current': isLast ? 'page' : undefined,
                   className: cp((child as React.ReactElement<any>).props.className, isLast ? styles.lastItem : styles.item)
                }) : child}
                {!isLast && (
                  <span className={styles.separator} aria-hidden="true">
                    {separator}
                  </span>
                )}
              </li>
            );
          })}
        </ol>
      </nav>
    );
  }
);
Breadcrumbs.displayName = "Breadcrumbs";

/* ============================================================
   Button.module.css
   Uses data-* attribute selectors — works across all bundlers.
   All colors derived from CSS custom properties (theme tokens).
   ============================================================ */

.button {
  /* Layout */
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-2, 8px);
  position: relative;
  box-sizing: border-box;
  min-width: 64px;

  /* Typography */
  font-family: var(--font-family, system-ui, -apple-system, sans-serif);
  font-weight: var(--font-weight-medium, 500);
  line-height: 1.75;
  letter-spacing: 0.02857em;
  text-transform: uppercase;
  white-space: nowrap;
  text-decoration: none;

  /* Visual */
  border-radius: var(--radius-md, 4px);
  border: 1px solid transparent;
  background-color: transparent;
  outline: none;
  cursor: pointer;
  user-select: none;

  /* Motion */
  transition:
    background-color var(--transition-fast, 150ms ease),
    border-color var(--transition-fast, 150ms ease),
    box-shadow var(--transition-fast, 150ms ease),
    color var(--transition-fast, 150ms ease);
}

/* ---- Focus-visible ring (accessibility) ---- */
.button:focus-visible {
  outline: 2px solid var(--color-focus-ring, var(--primary, #1976d2));
  outline-offset: 2px;
}

/* ============================================================
   SIZES — via data-size attribute
   ============================================================ */
.button[data-size="small"] {
  padding: var(--spacing-1, 4px) var(--spacing-3, 10px);
  font-size: var(--font-size-xs, 0.8125rem);
  min-width: 48px;
}

.button[data-size="medium"] {
  padding: var(--spacing-2, 6px) var(--spacing-4, 16px);
  font-size: var(--font-size-sm, 0.875rem);
}

.button[data-size="large"] {
  padding: var(--spacing-2, 8px) var(--spacing-6, 22px);
  font-size: var(--font-size-md, 0.9375rem);
}

/* ---- Full width ---- */
.button[data-full-width] {
  width: 100%;
}

/* ============================================================
   VARIANT: contained
   ============================================================ */
.button[data-variant="contained"] {
  box-shadow: var(--shadow-sm, 0px 2px 4px rgba(0, 0, 0, 0.15));
}

.button[data-variant="contained"][data-color="primary"] {
  background-color: var(--primary, #1976d2);
  color: var(--primary-foreground, #ffffff);
  border-color: var(--primary, #1976d2);
}
.button[data-variant="contained"][data-color="primary"]:hover:not(:disabled) {
  background-color: var(--primary-hover, color-mix(in srgb, var(--primary, #1976d2) 88%, black));
  border-color: var(--primary-hover, color-mix(in srgb, var(--primary, #1976d2) 88%, black));
}

.button[data-variant="contained"][data-color="secondary"] {
  background-color: var(--secondary, #9c27b0);
  color: var(--secondary-foreground, #ffffff);
  border-color: var(--secondary, #9c27b0);
}
.button[data-variant="contained"][data-color="secondary"]:hover:not(:disabled) {
  background-color: var(--secondary-hover, color-mix(in srgb, var(--secondary, #9c27b0) 88%, black));
  border-color: var(--secondary-hover, color-mix(in srgb, var(--secondary, #9c27b0) 88%, black));
}

.button[data-variant="contained"][data-color="error"] {
  background-color: var(--error, #d32f2f);
  color: var(--error-foreground, #ffffff);
  border-color: var(--error, #d32f2f);
}
.button[data-variant="contained"][data-color="error"]:hover:not(:disabled) {
  background-color: var(--error-hover, color-mix(in srgb, var(--error, #d32f2f) 88%, black));
  border-color: var(--error-hover, color-mix(in srgb, var(--error, #d32f2f) 88%, black));
}

.button[data-variant="contained"][data-color="warning"] {
  background-color: var(--warning, #ed6c02);
  color: var(--warning-foreground, #ffffff);
  border-color: var(--warning, #ed6c02);
}
.button[data-variant="contained"][data-color="warning"]:hover:not(:disabled) {
  background-color: var(--warning-hover, color-mix(in srgb, var(--warning, #ed6c02) 88%, black));
  border-color: var(--warning-hover, color-mix(in srgb, var(--warning, #ed6c02) 88%, black));
}

.button[data-variant="contained"][data-color="info"] {
  background-color: var(--info, #0288d1);
  color: var(--info-foreground, #ffffff);
  border-color: var(--info, #0288d1);
}
.button[data-variant="contained"][data-color="info"]:hover:not(:disabled) {
  background-color: var(--info-hover, color-mix(in srgb, var(--info, #0288d1) 88%, black));
  border-color: var(--info-hover, color-mix(in srgb, var(--info, #0288d1) 88%, black));
}

.button[data-variant="contained"][data-color="success"] {
  background-color: var(--success, #2e7d32);
  color: var(--success-foreground, #ffffff);
  border-color: var(--success, #2e7d32);
}
.button[data-variant="contained"][data-color="success"]:hover:not(:disabled) {
  background-color: var(--success-hover, color-mix(in srgb, var(--success, #2e7d32) 88%, black));
  border-color: var(--success-hover, color-mix(in srgb, var(--success, #2e7d32) 88%, black));
}

/* ============================================================
   VARIANT: outlined
   ============================================================ */
.button[data-variant="outlined"][data-color="primary"] {
  color: var(--primary, #1976d2);
  border-color: var(--primary, #1976d2);
}
.button[data-variant="outlined"][data-color="primary"]:hover:not(:disabled) {
  background-color: color-mix(in srgb, var(--primary, #1976d2) 8%, transparent);
}

.button[data-variant="outlined"][data-color="secondary"] {
  color: var(--secondary, #9c27b0);
  border-color: var(--secondary, #9c27b0);
}
.button[data-variant="outlined"][data-color="secondary"]:hover:not(:disabled) {
  background-color: color-mix(in srgb, var(--secondary, #9c27b0) 8%, transparent);
}

.button[data-variant="outlined"][data-color="error"] {
  color: var(--error, #d32f2f);
  border-color: var(--error, #d32f2f);
}
.button[data-variant="outlined"][data-color="error"]:hover:not(:disabled) {
  background-color: color-mix(in srgb, var(--error, #d32f2f) 8%, transparent);
}

.button[data-variant="outlined"][data-color="warning"] {
  color: var(--warning, #ed6c02);
  border-color: var(--warning, #ed6c02);
}
.button[data-variant="outlined"][data-color="warning"]:hover:not(:disabled) {
  background-color: color-mix(in srgb, var(--warning, #ed6c02) 8%, transparent);
}

.button[data-variant="outlined"][data-color="info"] {
  color: var(--info, #0288d1);
  border-color: var(--info, #0288d1);
}
.button[data-variant="outlined"][data-color="info"]:hover:not(:disabled) {
  background-color: color-mix(in srgb, var(--info, #0288d1) 8%, transparent);
}

.button[data-variant="outlined"][data-color="success"] {
  color: var(--success, #2e7d32);
  border-color: var(--success, #2e7d32);
}
.button[data-variant="outlined"][data-color="success"]:hover:not(:disabled) {
  background-color: color-mix(in srgb, var(--success, #2e7d32) 8%, transparent);
}

/* ============================================================
   VARIANT: text
   ============================================================ */
.button[data-variant="text"][data-color="primary"] {
  color: var(--primary, #1976d2);
}
.button[data-variant="text"][data-color="primary"]:hover:not(:disabled) {
  background-color: color-mix(in srgb, var(--primary, #1976d2) 8%, transparent);
}

.button[data-variant="text"][data-color="secondary"] {
  color: var(--secondary, #9c27b0);
}
.button[data-variant="text"][data-color="secondary"]:hover:not(:disabled) {
  background-color: color-mix(in srgb, var(--secondary, #9c27b0) 8%, transparent);
}

.button[data-variant="text"][data-color="error"] {
  color: var(--error, #d32f2f);
}
.button[data-variant="text"][data-color="error"]:hover:not(:disabled) {
  background-color: color-mix(in srgb, var(--error, #d32f2f) 8%, transparent);
}

.button[data-variant="text"][data-color="warning"] {
  color: var(--warning, #ed6c02);
}
.button[data-variant="text"][data-color="warning"]:hover:not(:disabled) {
  background-color: color-mix(in srgb, var(--warning, #ed6c02) 8%, transparent);
}

.button[data-variant="text"][data-color="info"] {
  color: var(--info, #0288d1);
}
.button[data-variant="text"][data-color="info"]:hover:not(:disabled) {
  background-color: color-mix(in srgb, var(--info, #0288d1) 8%, transparent);
}

.button[data-variant="text"][data-color="success"] {
  color: var(--success, #2e7d32);
}
.button[data-variant="text"][data-color="success"]:hover:not(:disabled) {
  background-color: color-mix(in srgb, var(--success, #2e7d32) 8%, transparent);
}

/* ============================================================
   VARIANT: ghost
   ============================================================ */
.button[data-variant="ghost"] {
  color: var(--text-primary, rgba(0, 0, 0, 0.87));
}
.button[data-variant="ghost"]:hover:not(:disabled) {
  background-color: var(--action-hover, rgba(0, 0, 0, 0.04));
}

/* ============================================================
   DISABLED STATE
   ============================================================ */
.button:disabled,
.button[data-loading] {
  cursor: not-allowed;
  pointer-events: none;
}

.button[data-variant="contained"]:disabled {
  background-color: var(--action-disabled-bg, rgba(0, 0, 0, 0.12));
  color: var(--text-disabled, rgba(0, 0, 0, 0.26));
  border-color: transparent;
  box-shadow: none;
}

.button[data-variant="outlined"]:disabled,
.button[data-variant="text"]:disabled,
.button[data-variant="ghost"]:disabled {
  color: var(--text-disabled, rgba(0, 0, 0, 0.26));
  border-color: var(--action-disabled-bg, rgba(0, 0, 0, 0.12));
}

/* ============================================================
   LOADING STATE
   ============================================================ */
.button[data-loading] {
  pointer-events: none;
}

.spinner {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1em;
  height: 1em;
  flex-shrink: 0;
}

.spinner svg {
  width: 100%;
  height: 100%;
  animation: spin 0.75s linear infinite;
}

@keyframes spin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

.loading-text {
  opacity: 0.7;
}

/* ============================================================
   ICONS
   ============================================================ */
.icon-start,
.icon-end {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.125em;
  height: 1.125em;
  flex-shrink: 0;
}

import React from "react";
import styles from "./Button.module.css";
import { cp } from "../../../lib/utils";

export type ButtonVariant = "contained" | "outlined" | "text" | "ghost";
export type ButtonColor =
  | "primary"
  | "secondary"
  | "error"
  | "warning"
  | "info"
  | "success";
export type ButtonSize = "small" | "medium" | "large";

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  color?: ButtonColor;
  size?: ButtonSize;
  fullWidth?: boolean;
  loading?: boolean;
  startIcon?: React.ReactNode;
  endIcon?: React.ReactNode;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      variant = "contained",
      color = "primary",
      size = "medium",
      fullWidth = false,
      loading = false,
      disabled,
      startIcon,
      endIcon,
      children,
      ...props
    },
    ref
  ) => {
    const isDisabled = disabled || loading;

    return (
      <button
        ref={ref}
        data-variant={variant}
        data-color={color}
        data-size={size}
        data-full-width={fullWidth || undefined}
        data-loading={loading || undefined}
        disabled={isDisabled}
        aria-disabled={isDisabled}
        className={cp(styles.button, className)}
        {...props}
      >
        {loading && (
          <span className={styles.spinner} aria-hidden="true">
            <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <circle
                cx="12"
                cy="12"
                r="10"
                stroke="currentColor"
                strokeWidth="3"
                strokeLinecap="round"
                strokeDasharray="31.4 31.4"
              />
            </svg>
          </span>
        )}
        {startIcon && !loading && (
          <span className={styles["icon-start"]} aria-hidden="true">
            {startIcon}
          </span>
        )}
        <span className={loading ? styles["loading-text"] : undefined}>
          {children}
        </span>
        {endIcon && !loading && (
          <span className={styles["icon-end"]} aria-hidden="true">
            {endIcon}
          </span>
        )}
      </button>
    );
  }
);

Button.displayName = "Button";

