  align?: "flex-start" | "center" | "flex-end" | "stretch" | "baseline";
  wrap?: "nowrap" | "wrap" | "wrap-reverse";
  gap?: number | string;
}

export const Flex = React.forwardRef<HTMLDivElement, FlexProps>(
  ({ className, direction = "row", justify = "flex-start", align = "stretch", wrap = "nowrap", gap, style, ...props }, ref) => {
    return (
      <div
        ref={ref}
        className={cp(styles.flex, className)}
        data-direction={direction}
        data-justify={justify}
        data-align={align}
        data-wrap={wrap}
        style={{ gap, ...style }}
        {...props}
      />
    );
  }
);
Flex.displayName = "Flex";

/* ============================================================
   Grid.module.css
   ============================================================ */

.grid {
  box-sizing: border-box;
}

.container {
  display: flex;
  flex-wrap: wrap;
  width: 100%;
}

.item {
  box-sizing: border-box;
  margin: 0;
}

/* ============================================================
   SPACING
   ============================================================ */
/* Spacing uses negative margins on container and positive padding on items */
.container[data-spacing="1"] { width: calc(100% + var(--spacing-1)); margin-left: calc(-1 * var(--spacing-1)); margin-top: calc(-1 * var(--spacing-1)); }
.container[data-spacing="1"] > .item { padding-left: var(--spacing-1); padding-top: var(--spacing-1); }

.container[data-spacing="2"] { width: calc(100% + var(--spacing-2)); margin-left: calc(-1 * var(--spacing-2)); margin-top: calc(-1 * var(--spacing-2)); }
.container[data-spacing="2"] > .item { padding-left: var(--spacing-2); padding-top: var(--spacing-2); }

.container[data-spacing="3"] { width: calc(100% + var(--spacing-3)); margin-left: calc(-1 * var(--spacing-3)); margin-top: calc(-1 * var(--spacing-3)); }
.container[data-spacing="3"] > .item { padding-left: var(--spacing-3); padding-top: var(--spacing-3); }

.container[data-spacing="4"] { width: calc(100% + var(--spacing-4)); margin-left: calc(-1 * var(--spacing-4)); margin-top: calc(-1 * var(--spacing-4)); }
.container[data-spacing="4"] > .item { padding-left: var(--spacing-4); padding-top: var(--spacing-4); }

.container[data-spacing="6"] { width: calc(100% + var(--spacing-6)); margin-left: calc(-1 * var(--spacing-6)); margin-top: calc(-1 * var(--spacing-6)); }
.container[data-spacing="6"] > .item { padding-left: var(--spacing-6); padding-top: var(--spacing-6); }

/* ============================================================
   RESPONSIVE COLUMNS (12-column grid)
   ============================================================ */

/* XS Breakpoint (default) */
.item[data-xs="auto"] { flex-grow: 1; max-width: none; flex-basis: 0; }
.item[data-xs="true"] { flex-grow: 1; max-width: 100%; flex-basis: 0; }
.item[data-xs="1"]  { flex-basis: 8.333333%;  max-width: 8.333333%; }
.item[data-xs="2"]  { flex-basis: 16.666667%; max-width: 16.666667%; }
