.item[data-xs="11"] { flex-basis: 91.666667%; max-width: 91.666667%; }
.item[data-xs="12"] { flex-basis: 100%;       max-width: 100%; }

/* SM Breakpoint */
@media (min-width: 600px) {
  .item[data-sm="auto"] { flex-grow: 1; max-width: none; flex-basis: 0; }
  .item[data-sm="true"] { flex-grow: 1; max-width: 100%; flex-basis: 0; }
  .item[data-sm="1"]  { flex-basis: 8.333333%;  max-width: 8.333333%; }
