/* ============================================================
   Snackbar.module.css
   ============================================================ */

.root {
  z-index: 1400;
  position: fixed;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none; /* Let clicks pass through empty space */
  /* Invisible by default, transitions in */
  visibility: hidden;
}

.root[data-open] {
  visibility: visible;
}

/* ============================================================
   ANCHOR ORIGINS
   ============================================================ */
.root[data-vertical="top"] {
  top: 8px;
}
.root[data-vertical="bottom"] {
  bottom: 8px;
}

.root[data-horizontal="left"] {
  left: 8px;
  right: auto;
}
.root[data-horizontal="right"] {
  right: 8px;
  left: auto;
}
.root[data-horizontal="center"] {
  left: 50%;
  right: auto;
  transform: translateX(-50%);
}

@media (min-width: 600px) {
  .root[data-vertical="top"] { top: 24px; }
  .root[data-vertical="bottom"] { bottom: 24px; }
  .root[data-horizontal="left"] { left: 24px; }
  .root[data-horizontal="right"] { right: 24px; }
}

/* ============================================================
   CONTAINER & ANIMATIONS
   ============================================================ */
.container {
  pointer-events: auto;
  opacity: 0;
  transform: scale(0.8);
  transition: opacity var(--transition-normal, 200ms ease), transform var(--transition-normal, 200ms ease);
}

.root[data-open] .container {
  opacity: 1;
  transform: scale(1);
}

/* Slide animations based on origin */
.root[data-vertical="bottom"][data-horizontal="center"] .container {
  transform: translateY(100%);
}
.root[data-open][data-vertical="bottom"][data-horizontal="center"] .container {
  transform: translateY(0);
}

.root[data-vertical="top"][data-horizontal="center"] .container {
  transform: translateY(-100%);
}
.root[data-open][data-vertical="top"][data-horizontal="center"] .container {
  transform: translateY(0);
}

/* ============================================================
   CONTENT
   ============================================================ */
.content {
  font-family: var(--font-family, system-ui, -apple-system, sans-serif);
  font-size: var(--font-size-sm, 0.875rem);
  color: var(--background-paper, #ffffff);
  background-color: var(--text-primary, rgba(50, 50, 50, 0.95));
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  padding: 6px 16px;
  border-radius: var(--radius-sm, 4px);
  box-shadow: var(--shadow-md, 0px 3px 5px -1px rgba(0,0,0,0.2), 0px 6px 10px 0px rgba(0,0,0,0.14), 0px 1px 18px 0px rgba(0,0,0,0.12));
  min-width: 288px;
}

.message {
  padding: 8px 0;
  flex-grow: 1;
}

.action {
  display: flex;
  align-items: center;
  margin-left: auto;
  padding-left: 16px;
  margin-right: -8px;
}

import React, { useEffect } from "react";
import styles from "./Snackbar.module.css";
import { cp } from "../../../lib/utils";

export type SnackbarOrigin = {
  vertical: "top" | "bottom";
  horizontal: "left" | "center" | "right";
};

export interface SnackbarProps extends React.HTMLAttributes<HTMLDivElement> {
  open?: boolean;
  autoHideDuration?: number | null;
  onClose?: (event?: React.SyntheticEvent | Event, reason?: string) => void;
  message?: React.ReactNode;
  action?: React.ReactNode;
  anchorOrigin?: SnackbarOrigin;
}

export const Snackbar = React.forwardRef<HTMLDivElement, SnackbarProps>(
  (
    {
      className,
      open = false,
      autoHideDuration = null,
      onClose,
      message,
      action,
      anchorOrigin = { vertical: "bottom", horizontal: "left" },
      children,
      ...props
    },
    ref
  ) => {
    useEffect(() => {
      if (open && autoHideDuration != null && autoHideDuration > 0) {
        const timer = setTimeout(() => {
          onClose?.(undefined, "timeout");
        }, autoHideDuration);
        return () => clearTimeout(timer);
      }
    }, [open, autoHideDuration, onClose]);

    // We keep it in the DOM to allow for exit animations via CSS.
    // If you prefer to unmount completely, you can conditionally render based on a local state synced with `open`.

    return (
      <div
        ref={ref}
        role="presentation"
        className={cp(styles.root, className)}
        data-vertical={anchorOrigin.vertical}
        data-horizontal={anchorOrigin.horizontal}
        data-open={open || undefined}
        {...props}
      >
        <div className={styles.container} role="alert" aria-live="polite">
          {children ? (
            children
          ) : (
            <div className={styles.content}>
              <div className={styles.message}>{message}</div>
              {action && <div className={styles.action}>{action}</div>}
            </div>
          )}
        </div>
      </div>
    );
  }
);

Snackbar.displayName = "Snackbar";

/* ============================================================
   Switch.module.css
   ============================================================ */

.switch-root {
  display: inline-flex;
  align-items: center;
  position: relative;
  font-family: var(--font-family, system-ui, -apple-system, sans-serif);
  vertical-align: middle;
  gap: var(--spacing-2, 8px);
}

.switch-container {
  display: inline-flex;
  align-items: center;
  position: relative;
  /* The size of the click target padding */
  padding: var(--spacing-1, 4px);
  margin: calc(var(--spacing-1, 4px) * -1);
}

/* ============================================================
   NATIVE INPUT (Visually Hidden)
   ============================================================ */
.input {
  cursor: pointer;
  position: absolute;
  opacity: 0;
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  margin: 0;
  padding: 0;
  z-index: 1;
}

/* ============================================================
   CUSTOM CONTROL (Track and Thumb)
   ============================================================ */
.track {
  display: flex;
  align-items: center;
  border-radius: var(--radius-full, 9999px);
  background-color: var(--action-disabled-bg, rgba(0, 0, 0, 0.38));
  transition: background-color var(--transition-fast, 150ms ease), box-shadow var(--transition-fast, 150ms ease);
  position: relative;
}

.thumb {
  border-radius: 50%;
  background-color: var(--background-paper, #ffffff);
  box-shadow: var(--shadow-sm, 0px 1px 2px rgba(0, 0, 0, 0.08));
  transition: transform var(--transition-fast, 150ms ease);
  position: absolute;
}

/* ============================================================
   STATES (Checked, Focus, Disabled)
   ============================================================ */

/* Hover state on track (optional, usually thumb gets a hover halo in material design, but let's keep it simple or add halo) */
.switch-root:not([data-disabled]) .input:hover ~ .track {
  box-shadow: 0 0 0 4px var(--action-hover, rgba(0, 0, 0, 0.04));
}

/* Focus-visible ring */
.input:focus-visible ~ .track {
  box-shadow: 0 0 0 3px var(--color-focus-ring, var(--primary, #1976d2));
}

/* Checked state - thumb position */
.input:checked ~ .track .thumb {
  /* We will set the transform translation based on size later */
}

/* Colors for Checked State */
.switch-root[data-color="primary"] .input:checked ~ .track {
  background-color: var(--primary, #1976d2);
}
.switch-root[data-color="secondary"] .input:checked ~ .track {
  background-color: var(--secondary, #9c27b0);
}
.switch-root[data-color="error"] .input:checked ~ .track {
  background-color: var(--error, #d32f2f);
}
.switch-root[data-color="warning"] .input:checked ~ .track {
  background-color: var(--warning, #ed6c02);
}
.switch-root[data-color="info"] .input:checked ~ .track {
  background-color: var(--info, #0288d1);
}
.switch-root[data-color="success"] .input:checked ~ .track {
  background-color: var(--success, #2e7d32);
}

/* Disabled state */
.switch-root[data-disabled] {
  cursor: not-allowed;
}
.switch-root[data-disabled] .input {
  cursor: not-allowed;
}
.switch-root[data-disabled] .track {
  background-color: var(--action-disabled-bg, rgba(0, 0, 0, 0.12));
}
.switch-root[data-disabled] .thumb {
  background-color: var(--background-subtle, #f5f5f5);
  box-shadow: none;
}
.switch-root[data-disabled] .label {
  color: var(--text-disabled, rgba(0, 0, 0, 0.38));
}

/* ============================================================
   SIZES
   ============================================================ */
/* Small */
.switch-root[data-size="small"] .track {
  width: 28px;
  height: 16px;
}
.switch-root[data-size="small"] .thumb {
  width: 12px;
  height: 12px;
  left: 2px;
}
.switch-root[data-size="small"] .input:checked ~ .track .thumb {
  transform: translateX(12px);
}

/* Medium */
.switch-root[data-size="medium"] .track {
  width: 36px;
  height: 20px;
}
.switch-root[data-size="medium"] .thumb {
  width: 16px;
  height: 16px;
  left: 2px;
}
.switch-root[data-size="medium"] .input:checked ~ .track .thumb {
  transform: translateX(16px);
}

/* Large */
.switch-root[data-size="large"] .track {
  width: 44px;
  height: 24px;
}
.switch-root[data-size="large"] .thumb {
  width: 20px;
  height: 20px;
  left: 2px;
}
.switch-root[data-size="large"] .input:checked ~ .track .thumb {
  transform: translateX(20px);
}

/* ============================================================
   LABEL
   ============================================================ */
.label {
  cursor: pointer;
  font-size: var(--font-size-md, 1rem);
  color: var(--text-primary, rgba(0, 0, 0, 0.87));
  user-select: none;
}

