  color: var(--secondary, #9c27b0);
}

.tab[aria-disabled="true"] {
  opacity: 0.38;
  cursor: default;
  pointer-events: none;
}

/* Icon Positions */
.tabIcon {
  display: inline-flex;
  margin-bottom: var(--spacing-1, 4px);
}
.tabIcon svg {
  width: 24px;
  height: 24px;
}

.tab[data-icon-position="top"] { flex-direction: column; }
.tab[data-icon-position="bottom"] { flex-direction: column-reverse; }
.tab[data-icon-position="bottom"] .tabIcon { margin-bottom: 0; margin-top: var(--spacing-1, 4px); }
.tab[data-icon-position="start"] { flex-direction: row; }
.tab[data-icon-position="start"] .tabIcon { margin-bottom: 0; margin-right: var(--spacing-2, 8px); }
.tab[data-icon-position="end"] { flex-direction: row-reverse; }
.tab[data-icon-position="end"] .tabIcon { margin-bottom: 0; margin-left: var(--spacing-2, 8px); }

/* ============================================================
   TAB PANEL
   ============================================================ */
.tabPanel {
  padding: var(--spacing-6, 24px);
  font-family: var(--font-family, system-ui, -apple-system, sans-serif);
}

import React, { Children, isValidElement, cloneElement, useState, useRef, useEffect } from "react";
import styles from "./Tabs.module.css";
import { cp } from "../../../lib/utils";

// ==========================================
// Tabs Component
// ==========================================
export interface TabsProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  value: number;
  onChange: (event: React.SyntheticEvent, newValue: number) => void;
  variant?: "standard" | "fullWidth";
  color?: "primary" | "secondary";
}

export const Tabs = React.forwardRef<HTMLDivElement, TabsProps>(
  (
    { className, value, onChange, variant = "standard", color = "primary", children, ...props },
    ref
  ) => {
    const tabsRef = useRef<HTMLDivElement>(null);
    const combinedRef = (ref || tabsRef) as React.MutableRefObject<HTMLDivElement | null>;
    const [indicatorStyle, setIndicatorStyle] = useState({ left: 0, width: 0 });

    useEffect(() => {
      // Calculate indicator position based on the selected tab
      // Using a timeout to ensure DOM layout is complete before measuring
      const timeoutId = setTimeout(() => {
        if (combinedRef.current) {
          const selectedTab = combinedRef.current.querySelector(
            `[role="tab"][aria-selected="true"]`
          ) as HTMLElement;

          if (selectedTab) {
            setIndicatorStyle({
              left: selectedTab.offsetLeft,
              width: selectedTab.offsetWidth,
            });
          }
        }
      }, 0);
      return () => clearTimeout(timeoutId);
    }, [value, combinedRef, children]);

    return (
      <div
        ref={combinedRef}
        role="tablist"
        className={cp(styles.tabsRoot, className)}
        data-variant={variant}
        data-color={color}
        {...props}
      >
        <div className={styles.tabsScroller}>
          <div className={styles.tabsFlexContainer}>
            {Children.map(children, (child, index) => {
              if (isValidElement(child)) {
                return cloneElement(child as React.ReactElement<any>, {
                  selected: value === index,
                  onClick: (e: React.SyntheticEvent) => {
                    const element = child as React.ReactElement<any>;
                    if (element.props.disabled) return;
                    if (element.props.onClick) element.props.onClick(e);
                    onChange(e, index);
                  },
                });
              }
              return child;
            })}
          </div>
          <span
            className={styles.indicator}
            style={{ left: indicatorStyle.left, width: indicatorStyle.width }}
          />
        </div>
      </div>
    );
  }
);
Tabs.displayName = "Tabs";

// ==========================================
// Tab Component
// ==========================================
export interface TabProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  label?: React.ReactNode;
  icon?: React.ReactNode;
  iconPosition?: "top" | "bottom" | "start" | "end";
  selected?: boolean;
}

export const Tab = React.forwardRef<HTMLButtonElement, TabProps>(
  (
    { className, label, icon, iconPosition = "top", selected, disabled, ...props },
    ref
  ) => {
    return (
      <button
        ref={ref}
        role="tab"
        aria-selected={selected}
        aria-disabled={disabled}
        tabIndex={selected ? 0 : -1}
        className={cp(styles.tab, className)}
        data-icon-position={iconPosition}
        disabled={disabled}
        {...props}
      >
        {icon && <span className={styles.tabIcon}>{icon}</span>}
        {label}
      </button>
    );
  }
);
Tab.displayName = "Tab";

// ==========================================
// TabPanel Component
// ==========================================
export interface TabPanelProps extends React.HTMLAttributes<HTMLDivElement> {
  value: number;
  index: number;
}

export const TabPanel = React.forwardRef<HTMLDivElement, TabPanelProps>(
  ({ className, children, value, index, ...props }, ref) => {
    const hidden = value !== index;
    return (
      <div
        ref={ref}
        role="tabpanel"
        hidden={hidden}
        className={cp(styles.tabPanel, className)}
        {...props}
      >
        {!hidden && children}
      </div>
    );
  }
);
TabPanel.displayName = "TabPanel";

/* ============================================================
   Tooltip.module.css
   ============================================================ */

.wrapper {
  display: inline-block;
  position: relative;
  cursor: pointer;
}

.tooltip {
  position: absolute;
  z-index: 1500;
  background-color: var(--text-primary, rgba(97, 97, 97, 0.9));
  color: var(--background-paper, #ffffff);
  border-radius: var(--radius-sm, 4px);
  padding: var(--spacing-1, 4px) var(--spacing-2, 8px);
  font-family: var(--font-family, system-ui, -apple-system, sans-serif);
  font-size: var(--font-size-xs, 0.6875rem);
  font-weight: var(--font-weight-medium, 500);
  line-height: 1.4;
  white-space: nowrap;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: scale(0.9);
  transition: opacity var(--transition-fast, 150ms ease), transform var(--transition-fast, 150ms ease);
}

.wrapper:hover .tooltip,
.wrapper:focus-within .tooltip {
  opacity: 1;
  visibility: visible;
  transform: scale(1);
  /* Slight delay for hover out */
  transition-delay: 50ms;
}

/* ============================================================
   PLACEMENTS
   ============================================================ */

/* Top */
.wrapper[data-placement="top"] .tooltip {
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%) scale(0.9);
  margin-bottom: var(--spacing-2, 8px);
}
.wrapper[data-placement="top"]:hover .tooltip,
.wrapper[data-placement="top"]:focus-within .tooltip {
  transform: translateX(-50%) scale(1);
}

/* Bottom */
.wrapper[data-placement="bottom"] .tooltip {
  top: 100%;
  left: 50%;
  transform: translateX(-50%) scale(0.9);
  margin-top: var(--spacing-2, 8px);
}
.wrapper[data-placement="bottom"]:hover .tooltip,
.wrapper[data-placement="bottom"]:focus-within .tooltip {
  transform: translateX(-50%) scale(1);
}

/* Left */
.wrapper[data-placement="left"] .tooltip {
  right: 100%;
  top: 50%;
  transform: translateY(-50%) scale(0.9);
  margin-right: var(--spacing-2, 8px);
}
.wrapper[data-placement="left"]:hover .tooltip,
.wrapper[data-placement="left"]:focus-within .tooltip {
  transform: translateY(-50%) scale(1);
}

/* Right */
.wrapper[data-placement="right"] .tooltip {
  left: 100%;
  top: 50%;
  transform: translateY(-50%) scale(0.9);
  margin-left: var(--spacing-2, 8px);
}
.wrapper[data-placement="right"]:hover .tooltip,
.wrapper[data-placement="right"]:focus-within .tooltip {
  transform: translateY(-50%) scale(1);
}

/* ============================================================
   ARROW
   ============================================================ */
.arrow {
  position: absolute;
  width: 8px;
  height: 8px;
  background-color: var(--text-primary, rgba(97, 97, 97, 0.9));
  transform: rotate(45deg);
  z-index: -1;
}

.wrapper[data-placement="top"] .arrow {
  bottom: -4px;
  left: calc(50% - 4px);
}

.wrapper[data-placement="bottom"] .arrow {
  top: -4px;
  left: calc(50% - 4px);
}

.wrapper[data-placement="left"] .arrow {
  right: -4px;
  top: calc(50% - 4px);
}

.wrapper[data-placement="right"] .arrow {
  left: -4px;
  top: calc(50% - 4px);
}

import React from "react";
import styles from "./Tooltip.module.css";
import { cp } from "../../../lib/utils";

export type TooltipPlacement = "top" | "bottom" | "left" | "right";

export interface TooltipProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  title: React.ReactNode;
  placement?: TooltipPlacement;
  children: React.ReactNode;
  arrow?: boolean;
}

export const Tooltip = React.forwardRef<HTMLDivElement, TooltipProps>(
  (
    { className, title, placement = "bottom", children, arrow = false, ...props },
    ref
  ) => {
    return (
      <div
        ref={ref}
        className={cp(styles.wrapper, className)}
        data-placement={placement}
        data-arrow={arrow || undefined}
        {...props}
      >
        {children}
        <div className={styles.tooltip} role="tooltip">
          {title}
          {arrow && <span className={styles.arrow} />}
        </div>
      </div>
    );
  }
);

Tooltip.displayName = "Tooltip";
